/** The operations this facade does not expose, each with its reason. */
export const CAT_FACTORY_OMITTED_OPERATIONS: readonly CatFactoryOmittedOperation[] = [
  {
    operationId: 'streamPublicJobEvents',
    route: 'GET /api/v1/jobs/{id}/events',
    sdkCall: 'client.jobs.stream()',
    reason: 'A tool call returns one result, so it has no channel to stream an open-ended event feed over. Poll `jobs_get` instead, or consume the SSE endpoint through an SDK.',
  },
  {
    operationId: 'streamPublicTaskRun',
    route: 'GET /api/v1/tasks/{taskId}/events',
    sdkCall: 'client.tasks.stream()',
    reason: 'A tool call returns one result, so it has no channel to stream a run over. Poll `tasks_get_run` instead (a parked run waits for a human indefinitely, so a bounded "wait for the run to finish" tool would be a timeout dressed up as an answer), or consume the SSE endpoint through an SDK.',
  },
]

